package com.projecteden.cheer.service;
import java.time.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.projecteden.character.domain.Character; import com.projecteden.character.repository.CharacterRepository; import com.projecteden.cheer.domain.Cheer; import com.projecteden.cheer.dto.CheerResponseDTO; import com.projecteden.cheer.repository.CheerRepository; import com.projecteden.common.exception.ResourceNotFoundException; import com.projecteden.friend.service.FriendService; import com.projecteden.notification.domain.NotificationType; import com.projecteden.notification.service.NotificationService; import com.projecteden.user.domain.User; import com.projecteden.user.repository.UserRepository;
@Service public class CheerService { private final CheerRepository cheers;private final UserRepository users;private final FriendService friends;private final CharacterRepository characters;private final NotificationService notifications;private final Clock clock; public CheerService(CheerRepository cheers,UserRepository users,FriendService friends,CharacterRepository characters,NotificationService notifications,Clock clock){this.cheers=cheers;this.users=users;this.friends=friends;this.characters=characters;this.notifications=notifications;this.clock=clock;}
	@Transactional public CheerResponseDTO cheer(Long senderId,Long receiverId){User s=user(senderId),r=user(receiverId);if(!friends.areFriends(s,r))throw new IllegalArgumentException("친구에게만 응원할 수 있습니다.");LocalDate d=LocalDate.now(clock);LocalDateTime start=d.atStartOfDay(),end=d.plusDays(1).atStartOfDay();if(cheers.existsBySenderAndReceiverAndCheeredAtBetween(s,r,start,end))throw new IllegalArgumentException("오늘 이미 이 친구를 응원했습니다.");cheers.save(Cheer.create(s,r));Character c=characters.findByUserId(r.getId()).orElseThrow(()->new ResourceNotFoundException("캐릭터를 찾을 수 없습니다."));c.addExp(5);notifications.create(r,NotificationType.CHEER_RECEIVED,s.getNickname()+"님이 응원을 보냈습니다.");return new CheerResponseDTO("친구에게 응원을 보냈습니다.",5);}
	private User user(Long id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("사용자를 찾을 수 없습니다."));}}
